package com.dongqh.luckyhub.payment;
import com.dongqh.luckyhub.payment.dto.*;import com.dongqh.luckyhub.payment.enums.*;import com.dongqh.luckyhub.payment.service.PaymentService;import org.junit.jupiter.api.Test;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import static org.assertj.core.api.Assertions.*;
@SpringBootTest class PaymentServiceTests extends PaymentTestFixture { @Autowired PaymentService payments;
 @Test void verifiesSignatureAndProcessesSuccessExactlyOnce(){createOrder("PAY-ORDER");var p=payments.create(userId,new CreatePaymentCommand("PAY-1","PAY-ORDER"));assertThat(p.amountCent()).isEqualTo(9000L);assertThatThrownBy(()->payments.callback(new PaymentCallbackCommand("PAY-1",PaymentResult.SUCCESS,null,"bad"))).hasMessageContaining("签名");String sig=payments.signForSimulation("PAY-1",PaymentResult.SUCCESS,9000L);var first=payments.callback(new PaymentCallbackCommand("PAY-1",PaymentResult.SUCCESS,null,sig));var repeated=payments.callback(new PaymentCallbackCommand("PAY-1",PaymentResult.SUCCESS,null,sig));assertThat(first.status()).isEqualTo(PaymentStatus.SUCCESS);assertThat(repeated.id()).isEqualTo(first.id());assertThat(orders.get(userId,"PAY-ORDER").status().name()).isEqualTo("PAID");assertThat(inventory.get(skuId,"MALL").consumedStock()).isOne();assertThat(coupons.getMine(userId,couponId).status().name()).isEqualTo("USED");}
 @Test void processingAndFailureDoNotConsumeAssets(){createOrder("WAIT-ORDER");payments.create(userId,new CreatePaymentCommand("PAY-WAIT","WAIT-ORDER"));String processing=payments.signForSimulation("PAY-WAIT",PaymentResult.PROCESSING,9000L);assertThat(payments.callback(new PaymentCallbackCommand("PAY-WAIT",PaymentResult.PROCESSING,null,processing)).status()).isEqualTo(PaymentStatus.PENDING);String failure=payments.signForSimulation("PAY-WAIT",PaymentResult.FAILURE,9000L);assertThat(payments.callback(new PaymentCallbackCommand("PAY-WAIT",PaymentResult.FAILURE,"余额不足",failure)).status()).isEqualTo(PaymentStatus.FAILED);assertThat(orders.get(userId,"WAIT-ORDER").status().name()).isEqualTo("PENDING_PAYMENT");assertThat(inventory.get(skuId,"MALL").reservedStock()).isOne();}
}
